expressionScopeAllowsArrowHead(scope: any): boolean {
  return !!(scope && scope.canBeArrowParameterDeclaration());
}

expressionScopeIsParameter(scope: any): boolean {
  return !!(scope && scope.isCertainlyParameterDeclaration());
}

recordArrowHeadDeclarationError(scope: any, pos: number, template: any): void {
  scope.recordDeclarationError(pos, template);
}

clearArrowHeadDeclarationError(scope: any, pos: number): void {
  scope.clearDeclarationError(pos);
}

captureParameterInitializerError(
  handler: any,
  pos: number,
  template: any,
): void {
  const stack = handler.stack;
  let i = stack.length - 1;
  let scope = stack[i];
  while (!this.expressionScopeIsParameter(scope)) {
    if (this.expressionScopeAllowsArrowHead(scope)) {
      this.recordArrowHeadDeclarationError(scope, pos, template);
    } else {
      return;
    }
    scope = stack[--i];
  }
  this.raise(pos, template);
}

captureParenthesizedIdentifierError(
  handler: any,
  pos: number,
  template: any,
): void {
  const scope = handler.stack[handler.stack.length - 1];
  if (this.expressionScopeIsParameter(scope)) {
    this.raise(pos, template);
    return;
  }
  if (this.expressionScopeAllowsArrowHead(scope)) {
    this.recordArrowHeadDeclarationError(scope, pos, template);
  }
}

captureAsyncArrowParameterError(
  handler: any,
  pos: number,
  template: any,
): void {
  const stack = handler.stack;
  let i = stack.length - 1;
  let scope = stack[i];
  while (this.expressionScopeAllowsArrowHead(scope)) {
    if (scope.type === 2) {
      this.recordArrowHeadDeclarationError(scope, pos, template);
    }
    scope = stack[--i];
  }
}

validateArrowHeadAsPattern(handler: any): void {
  const stack = handler.stack;
  const currentScope = stack[stack.length - 1];
  if (!this.expressionScopeAllowsArrowHead(currentScope)) return;
  currentScope.iterateErrors((template, pos) => {
    this.raise(pos, template);
    let i = stack.length - 2;
    let scope = stack[i];
    while (this.expressionScopeAllowsArrowHead(scope)) {
      this.clearArrowHeadDeclarationError(scope, pos);
      scope = stack[--i];
    }
  });
}

