    this.stack.pop();
  }""","""  enter(scope) {
    this.stack.push(scope);
  }

  exit() {
    this.stack.pop();
  }""")
s=s.replace("""  recordParameterInitializerError(pos, template) {
    const {
      stack
    } = this;
