    let scope = stack[i];

    while (!scope.isCertainlyParameterDeclaration()) {
      if (scope.canBeArrowParameterDeclaration()) {
        console.log("DEBUG record", pos, template, "stack types:", stack.map(s => s.type));
      } else {
        return;
      }

      scope = stack[--i];
    }

    console.log("DEBUG raise", pos, template, "stack types:", stack.map(s => s.type));
    this.raise(pos, template);
  }""","""  recordParameterInitializerError(pos, template) {
    const {
      stack
    } = this;
    let i = stack.length - 1;
    let scope = stack[i];

    while (!scope.isCertainlyParameterDeclaration()) {
      if (scope.canBeArrowParameterDeclaration()) {
        scope.recordDeclarationError(pos, template);
      } else {
        return;
      }

      scope = stack[--i];
    }

    this.raise(pos, template);
  }""")
s=s.replace('new ExpressionScopeHandler(this.raise.bind(this), this)','new ExpressionScopeHandler(this.raise.bind(this))')
s=s.replace("""  constructor(raise, parser) {
    this.stack = [new ExpressionScope()];
    this.raise = raise;
    this.parser = parser;
  }""","""  constructor(raise) {
    this.stack = [new ExpressionScope()];
    this.raise = raise;
  }""")
# apply the fix: move expressionScope.exit() out of else branch in parseFunctionBody
old="""      });
      this.prodParam.exit();
      this.expressionScope.exit();
      this.state.labels = oldLabels;
    }
  }"""
new="""      });
      this.prodParam.exit();
      this.state.labels = oldLabels;
    }
    this.expressionScope.exit();
  }"""
assert s.count(old)==1
s=s.replace(old,new)
open(p,'w').write(s)
print("done")
EOF

