const parser = require(\"./packages/babel-parser/lib\").parse;
const cases = [
  \"(async function () { function f(_=()=>null) {} await null; })\",
  \"(function* () { function f(_=()=>null) {} yield; })\",
  \"async function f(a = () => 1) { await 2; }\",
  \"function* g(a = () => 1) { yield 2; }\",
  \"const h = () => null; async function x() { await h(); }\",
  \"(async function () { function f(_=async()=>await x) {} await null; })\",
  \"async () => await null\",
  \"function f(_ = () => { await 1; }) {}\"  // invalid: await inside non-async arrow body
];
for (const code of cases) {
  try { parser(code, {}); console.log(\"OK  :\", code); } catch (e) { console.log(\"ERR :\", code, \"->\", e.message); }
}
"' && docker exec cli-eval-opencode-babel__babel-13928-b7a377bb sh -lc 'cd /testbed && yarn jest packages/babel-parser --silent 2>&1 | tail -4'

